(function(){"use strict";self.onmessage=async s=>{const{id:t,blob:r}=s.data||{};try{if(!(r instanceof Blob))throw new Error("blob required");const e=await crypto.subtle.digest("SHA-256",await r.arrayBuffer()),a=Array.from(new Uint8Array(e),o=>o.toString(16).padStart(2,"0")).join("");self.postMessage({id:t,type:"done",hash:a})}catch(e){self.postMessage({id:t,type:"error",message:e?.message||String(e)})}}})();
